#!/usr/bin/env python3
import sys, os, re, time, math, shutil, select, termios, tty, signal
from dataclasses import dataclass, field
from typing import List, Optional, Tuple

VERSION = "flamelens 0.3.1"
FOOTER_FLAME_BASE = "[hjkl: move cursor] [f/b: scroll] [enter/esc: zoom] [/: search] [#: search like cursor] [r: reset] [tab: switch view] [q: quit]"
FOOTER_TOP = "[j/k: move cursor] [f/b: scroll] [1: sort by total] [2: sort by own] [/: filter] [r: reset] [tab: switch view] [q: quit]"

@dataclass
class Node:
    name: str
    value: int = 0
    own: int = 0
    parent: Optional['Node'] = None
    children: List['Node'] = field(default_factory=list)
    order: int = 0
    x: int = 0
    w: int = 0
    y: int = 0

    def child(self, name: str, order_counter: List[int]):
        for c in self.children:
            if c.name == name:
                return c
        order_counter[0] += 1
        c = Node(name=name, parent=self, order=order_counter[0])
        self.children.append(c)
        return c

class Model:
    def __init__(self, data: str, sorted_flag: bool=False):
        self.data = data
        self.sorted_flag = sorted_flag
        self.root = Node('all')
        self._order_counter = [0]
        self.parse(data)
        self.apply_sort()

    def parse(self, data: str):
        for raw in data.splitlines():
            line = raw.rstrip('\r')
            if not line:
                continue
            # flamelens treats '#' at the first column as a comment, and otherwise
            # expects a decimal integer after the last literal space.  Trailing
            # whitespace makes the count invalid; tabs are not separators.
            if line.startswith('#'):
                continue
            if ' ' not in line:
                continue
            stack, count_s = line.rsplit(' ', 1)
            if count_s == '' or not count_s.isdigit():
                continue
            try:
                count = int(count_s)
            except Exception:
                continue
            stack = stack.strip()
            if not stack:
                continue
            frames = [p for p in stack.split(';') if p != '']
            if not frames:
                continue
            self.root.value += count
            cur = self.root
            for f in frames:
                cur = cur.child(f, self._order_counter)
                cur.value += count
            cur.own += count

    def apply_sort(self):
        if self.sorted_flag:
            self._sort_rec(self.root)

    def _sort_rec(self, n: Node):
        n.children.sort(key=lambda c: (-c.value, c.order))
        for c in n.children:
            self._sort_rec(c)

    def all_nodes(self):
        out=[]
        def rec(n):
            out.append(n)
            for c in n.children: rec(c)
        rec(self.root)
        return out

    def non_root_nodes(self):
        return [n for n in self.all_nodes() if n is not self.root]

class App:
    def __init__(self, model: Model, title: str, debug=False):
        self.model = model
        self.title = title
        self.debug = debug
        self.view = 'flame'
        self.selected = model.root
        self.zoom = model.root
        self.scroll = 0
        self.top_scroll = 0
        self.top_index = 0
        self.top_sort = 'own'
        self.top_filter = None
        self.mode = None  # 'search' or 'filter'
        self.input_buf = ''
        self.match_pattern = None
        self.match_nodes: List[Node] = []
        self.info = None
        self.running = True
        self.last_render_ms = 0.0
        self.last_layout_ms = 0.0
        self._last_rows: List[Node] = []

    # ---------- terminal helpers ----------
    def term_size(self):
        sz = shutil.get_terminal_size((80, 24))
        return max(20, sz.columns), max(8, sz.lines)

    def esc(self, s):
        sys.stdout.write(s)

    def move(self, r, c):
        self.esc(f"\x1b[{r};{c}H")

    def clear(self):
        self.esc("\x1b[2J")

    def sgr(self, *codes):
        if codes:
            self.esc("\x1b[" + ';'.join(str(c) for c in codes) + 'm')
        else:
            self.esc("\x1b[0m")

    def write_at(self, r, c, text, width=None):
        if width is not None:
            text = text[:width].ljust(width)
        self.move(r, c)
        sys.stdout.write(text)

    def line(self, r, w):
        self.write_at(r, 1, '─' * w)

    def header(self, w):
        self.line(1, w)
        if self.view == 'flame':
            left = " [Flamegraph] | Top"
        else:
            left = " Flamegraph | [Top]"
        self.write_at(2, 1, left)
        t = self.title
        tcol = max(len(left)+2, w//2 - len(t)//2 + 3)
        if tcol + len(t) - 1 < w - len("flamelens v0.3.1"):
            self.write_at(2, tcol, t[:max(0,w-tcol+1)])
        v = "flamelens v0.3.1"
        if w >= len(v):
            self.write_at(2, w-len(v)+1, v)
        self.line(3, w)

    def footer(self, h, w):
        if self.view == 'flame':
            foot = FOOTER_FLAME_BASE
            if self.match_pattern:
                foot = foot.replace('[r: reset]', '[n/N: next/prev match] [r: reset]')
        else:
            foot = FOOTER_TOP
        start = max(1, (w - len(foot))//2 + 1)
        self.write_at(h, start, foot[:w-start+1])

    # ---------- formatting ----------
    def pct(self, v, denom):
        if denom == 0:
            if v == 0:
                return "NaN"
            return "inf"
        return f"{(100.0*v/denom):.2f}"

    def node_detail(self, n: Node):
        total = self.model.root.value
        s = f"{n.name} [{n.value} samples, {self.pct(n.value,total)}% of all"
        if self.zoom is not self.model.root:
            s += f", {self.pct(n.value,self.zoom.value)}% of zoomed"
        s += "]"
        return s

    def match_detail(self):
        total = self.model.root.value
        val = sum(n.value for n in self.match_nodes)
        return f'"{self.match_pattern}" [{val} samples, {self.pct(val,total)}% of all]'

    def color_for(self, name):
        # Deterministic warm palette similar to flame graphs.
        h = 0
        for ch in name:
            h = (h * 131 + ord(ch)) & 0xffffffff
        r = 205 + (h % 51)
        g = 35 + ((h >> 8) % 200)
        b = 8 + ((h >> 16) % 48)
        return r,g,b

    # ---------- layout/render flamegraph ----------
    def path_to(self, n):
        p=[]
        while n is not None:
            p.append(n); n=n.parent
        return list(reversed(p))

    def visible_rows_end(self, h):
        bottom_title = h-3
        if self.debug:
            bottom_title = h-5
        elif self.mode in ('search','filter'):
            bottom_title = h-3
        elif self.match_pattern and self.info:
            bottom_title = h-7
        elif self.match_pattern:
            bottom_title = h-5
        elif self.info:
            bottom_title = h-5
        return max(4, bottom_title-1)

    def layout_flame(self, w, h):
        t0=time.time()
        rows=[]
        # ancestor path is always displayed at full width; descendants of zoom
        # are then laid out below the zoom frame.
        path = self.path_to(self.zoom)
        y = 4
        for n in path:
            n.x=0; n.w=w; n.y=y; rows.append(n); y += 1
        def rec(parent, depth_y):
            if parent.value <= 0 or parent.w <= 0:
                return
            cum = 0
            for c in parent.children:
                if c.value <= 0: continue
                x1 = parent.x + int(round(cum * parent.w / parent.value))
                cum += c.value
                x2 = parent.x + int(round(cum * parent.w / parent.value))
                cw = max(1, x2-x1)
                if x1 >= parent.x + parent.w: continue
                if x1 + cw > parent.x + parent.w:
                    cw = parent.x + parent.w - x1
                c.x=x1; c.w=cw; c.y=depth_y; rows.append(c)
                rec(c, depth_y+1)
        rec(self.zoom, y)
        rows.sort(key=lambda n: (n.y, n.x, n.order))
        self._last_rows = rows
        self.last_layout_ms = (time.time()-t0)*1000
        return rows

    def draw_frame(self, n, row, is_sel, is_match):
        w = max(0, n.w)
        if w <= 0: return
        label = (' ' + n.name)[:w].ljust(w)
        r,g,b = self.color_for(n.name)
        if n is self.model.root:
            r,g,b = 250,250,250
        fg = (10,10,10)
        if is_sel:
            fg = (225,225,225)
            r,g,b = max(80,r-35), max(20,g-80), max(0,b-20)
        elif is_match:
            r,g,b = 120,200,255
        self.move(row, n.x+1)
        self.esc(f"\x1b[38;2;{fg[0]};{fg[1]};{fg[2]};48;2;{r};{g};{b}m")
        sys.stdout.write(label)
        self.sgr(0)

    def render_flame(self, w, h):
        rows = self.layout_flame(w, h)
        graph_end = self.visible_rows_end(h)
        for n in rows:
            rr = n.y - self.scroll
            if 4 <= rr <= graph_end:
                self.draw_frame(n, rr, n is self.selected, n in self.match_nodes)
        # bottom panels
        if self.mode == 'search':
            self.write_section(h-3, w, 'Search')
            self.write_at(h-2, 1, self.input_buf[:w])
        else:
            r = h-3
            if self.match_pattern:
                r = h-5
                self.write_section(r, w, 'Match')
                self.write_at(r+1, 1, self.match_detail()[:w])
                r += 2
            if self.info:
                # If there is no match panel, Selected is shown above Info.
                if not self.match_pattern:
                    r = h-5
                    self.write_section(r, w, 'Selected')
                    self.write_at(r+1, 1, self.node_detail(self.selected)[:w])
                    r += 2
                self.write_section(r, w, 'Info')
                self.write_at(r+1, 1, self.info[:w])
            else:
                self.write_section(r, w, 'Selected')
                self.write_at(r+1, 1, self.node_detail(self.selected)[:w])
            if self.debug:
                self.write_section(h-3, w, 'Debug')
                self.write_at(h-2, 1, f"Debug: render:{self.last_render_ms:.2f}ms flamegraph:{self.last_layout_ms:.2f}ms"[:w])
        self.line(h-1, w)

    def write_section(self, r, w, name):
        text = name + ' '
        self.move(r,1)
        self.sgr(1,38,5,3,49)
        sys.stdout.write(text[:w])
        self.sgr(22,39,49)
        rem = w-len(text)
        if rem > 0:
            sys.stdout.write('─'*rem)

    # ---------- top table ----------
    def filtered_top_nodes(self):
        nodes = self.model.non_root_nodes()
        if self.top_filter:
            try:
                rx = re.compile(self.top_filter)
                nodes = [n for n in nodes if rx.search(n.name)]
            except re.error:
                nodes = []
        if self.top_sort == 'total':
            nodes.sort(key=lambda n: (-n.value, -n.own, n.order))
        else:
            nodes.sort(key=lambda n: (-n.own, -n.value, n.order))
        return nodes

    def fmt_val(self, v):
        return f"{v} ({self.pct(v, self.model.root.value)}%)"

    def render_top(self, w, h):
        nodes = self.filtered_top_nodes()
        total_strings = [self.fmt_val(n.value) for n in nodes] + ['Total [▼]' if self.top_sort=='total' else 'Total']
        own_strings = [self.fmt_val(n.own) for n in nodes] + ['Own [▼]' if self.top_sort=='own' else 'Own']
        tw = max(5, max(map(len,total_strings)) if total_strings else 5) + 3
        ow = max(3, max(map(len,own_strings)) if own_strings else 3) + 3
        header = ('Total [▼]' if self.top_sort=='total' else 'Total').ljust(tw) + ('Own [▼]' if self.top_sort=='own' else 'Own').ljust(ow) + 'Name'
        self.write_at(4,1,header[:w])
        max_rows = max(0, h-6)
        if self.top_index < self.top_scroll: self.top_scroll = self.top_index
        if self.top_index >= self.top_scroll + max_rows: self.top_scroll = self.top_index-max_rows+1
        for i,n in enumerate(nodes[self.top_scroll:self.top_scroll+max_rows]):
            row = 5+i
            s = self.fmt_val(n.value).ljust(tw) + self.fmt_val(n.own).ljust(ow) + n.name
            if self.top_scroll+i == self.top_index:
                self.move(row,1); self.esc("\x1b[38;2;225;225;225;48;2;70;70;70m"); sys.stdout.write(s[:w].ljust(min(w,len(s)))); self.sgr(0)
            else:
                self.write_at(row,1,s[:w])
        if self.mode == 'filter':
            self.write_section(h-3,w,'Filter')
            self.write_at(h-2,1,self.input_buf[:w])
        elif self.info:
            self.write_section(h-3,w,'Info')
            self.write_at(h-2,1,self.info[:w])
        self.line(h-1,w)

    # ---------- render loop ----------
    def render(self):
        t0=time.time()
        w,h = self.term_size()
        self.sgr(0)
        self.clear()
        self.header(w)
        if self.view == 'flame':
            self.render_flame(w,h)
        else:
            self.render_top(w,h)
        self.footer(h,w)
        self.sgr(0)
        self.esc("\x1b[?25l")
        sys.stdout.flush()
        self.last_render_ms = (time.time()-t0)*1000

    # ---------- input ----------
    def child_at_same_x(self, n):
        if not n.children: return n
        center = n.x + max(1,n.w)//2
        for c in n.children:
            if c.x <= center < c.x+c.w:
                return c
        return n.children[0]

    def sibling(self, n, delta):
        if not n.parent: return n
        sibs = n.parent.children
        try: idx=sibs.index(n)
        except ValueError: return n
        idx2 = idx + delta
        if 0 <= idx2 < len(sibs): return sibs[idx2]
        return n

    def select_node(self, n):
        self.selected = n
        # adjust scroll to selected y after a render/layout pass
        if n.y:
            w,h=self.term_size(); ge=self.visible_rows_end(h)
            if n.y-self.scroll < 4: self.scroll=max(0,n.y-4)
            if n.y-self.scroll > ge: self.scroll=max(0,n.y-ge)

    def update_matches(self, pat):
        self.info = None
        try:
            rx = re.compile(pat)
        except re.error:
            self.match_pattern = None
            self.match_nodes = []
            self.info = f"Invalid regex: {pat}"
            return
        self.match_pattern = pat
        self.match_nodes = [n for n in self.model.non_root_nodes() if rx.search(n.name)]

    def next_match(self, direction=1):
        if not self.match_nodes: return
        # order by rendered preorder/depth/x
        order = sorted(self.match_nodes, key=lambda n:(n.y or 9999, n.x, n.order))
        if self.selected not in order:
            if direction > 0:
                self.select_node(order[0])
            return
        idx=order.index(self.selected)+direction
        if 0 <= idx < len(order):
            self.select_node(order[idx])

    def reset(self):
        if self.view == 'flame':
            self.zoom = self.model.root
            self.selected = self.model.root
            self.scroll = 0
            self.match_pattern = None
            self.match_nodes = []
            self.info = None
        else:
            self.top_sort = 'own'
            self.top_filter = None
            self.info = None
            self.top_index = 0
            self.top_scroll = 0

    def handle_key(self, key):
        if self.mode in ('search','filter'):
            if key in ('\r','\n'):
                pat = self.input_buf
                if self.mode == 'search':
                    self.update_matches(pat)
                else:
                    try:
                        re.compile(pat)
                        self.top_filter = pat
                        self.info = None
                        self.top_index = 0
                        self.top_scroll = 0
                    except re.error:
                        self.info = f"Invalid regex: {pat}"
                self.mode = None; self.input_buf=''
            elif key == '\x1b':
                self.mode=None; self.input_buf=''
            elif key in ('\x7f','\b'):
                self.input_buf = self.input_buf[:-1]
            elif key >= ' ' and key != '\x7f':
                self.input_buf += key
            return
        if key in ('q','\x03'):
            self.running=False; return
        if key == '\t':
            self.view = 'top' if self.view=='flame' else 'flame'; return
        if self.view == 'top':
            nodes = self.filtered_top_nodes()
            if key in ('j','\x1b[B'):
                if self.top_index < len(nodes)-1: self.top_index += 1
            elif key in ('k','\x1b[A'):
                if self.top_index > 0: self.top_index -= 1
            elif key == 'f':
                self.top_index = min(len(nodes)-1, self.top_index+10) if nodes else 0
            elif key == 'b':
                self.top_index = max(0, self.top_index-10)
            elif key == '1':
                self.top_sort = 'total'; self.top_index=0; self.top_scroll=0
            elif key == '2':
                self.top_sort = 'own'; self.top_index=0; self.top_scroll=0
            elif key == '/':
                self.mode='filter'; self.input_buf=''
            elif key == 'r':
                self.reset()
            return
        # flame view
        if key in ('j','\x1b[B'):
            self.select_node(self.child_at_same_x(self.selected))
        elif key in ('k','\x1b[A'):
            if self.selected.parent: self.select_node(self.selected.parent)
        elif key in ('l','\x1b[C'):
            self.select_node(self.sibling(self.selected, 1))
        elif key in ('h','\x1b[D'):
            self.select_node(self.sibling(self.selected, -1))
        elif key in ('\r','\n'):
            self.zoom = self.selected
            self.scroll = 0
        elif key == '\x1b':
            self.zoom = self.model.root
            self.scroll = 0
        elif key == 'f':
            self.scroll += 10
        elif key == 'b':
            self.scroll = max(0,self.scroll-10)
        elif key == 'G':
            self.scroll = 10**6
        elif key == 'g':
            self.scroll = 0
        elif key == '/':
            self.mode='search'; self.input_buf=''
        elif key == '#':
            self.update_matches('^' + re.escape(self.selected.name) + '$')
        elif key == 'n':
            self.next_match(1)
        elif key == 'N':
            self.next_match(-1)
        elif key == 'r':
            self.reset()

    def read_key(self):
        ch = sys.stdin.read(1)
        if ch == '\x1b':
            # collect simple CSI arrow sequence if immediately available
            seq = ch
            r,_,_ = select.select([sys.stdin],[],[],0.02)
            if r:
                c2=sys.stdin.read(1); seq+=c2
                if c2 == '[':
                    r,_,_ = select.select([sys.stdin],[],[],0.02)
                    if r:
                        seq += sys.stdin.read(1)
            if seq in ('\x1b[A','\x1b[B','\x1b[C','\x1b[D'):
                return seq
            return '\x1b'
        return ch

    def run(self):
        old = None
        try:
            fd = sys.stdin.fileno()
            old = termios.tcgetattr(fd)
            tty.setcbreak(fd)
            self.esc("\x1b[?1049h\x1b[?25l")
            while self.running:
                self.render()
                r,_,_ = select.select([sys.stdin],[],[],0.1)
                if r:
                    k=self.read_key()
                    self.handle_key(k)
        finally:
            if old is not None:
                try: termios.tcsetattr(sys.stdin.fileno(), termios.TCSADRAIN, old)
                except Exception: pass
            self.sgr(0)
            self.esc("\x1b[?25l\x1b[?1049l\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1002l\x1b[?1000l\x1b[?25h")
            sys.stdout.flush()

# ---------- CLI ----------
def usage(prog):
    return f"Usage: {prog} [OPTIONS] [FILENAME]\n\nArguments:\n  [FILENAME]  Profile data filename\n\nOptions:\n      --sorted   Whether to sort the stacks by time spent\n      --echo     Print data to stdout on exit. Useful when piping to other tools\n      --debug    Show debug info\n  -h, --help     Print help\n  -V, --version  Print version\n"

def clap_error(prog, msg, tip=None):
    sys.stderr.write(f"error: {msg}\n\n")
    if tip:
        sys.stderr.write(f"  tip: {tip}\n\n")
    sys.stderr.write(f"Usage: {prog} [OPTIONS] [FILENAME]\n\nFor more information, try '--help'.\n")
    return 2

def parse_args(argv):
    prog = os.path.basename(argv[0]) or 'executable'
    sorted_flag=echo=debug=False
    filename=None
    after_dd=False
    i=1
    while i < len(argv):
        a=argv[i]
        if not after_dd and a == '--':
            after_dd=True; i+=1; continue
        if not after_dd and a in ('-h','--help'):
            sys.stdout.write(usage(prog)); return None
        if not after_dd and a in ('-V','--version'):
            sys.stdout.write(VERSION+'\n'); return None
        if not after_dd and a == '--sorted':
            sorted_flag=True; i+=1; continue
        if not after_dd and a == '--echo':
            echo=True; i+=1; continue
        if not after_dd and a == '--debug':
            debug=True; i+=1; continue
        if not after_dd and a.startswith('-'):
            tip = f"to pass '{a}' as a value, use '-- {a}'"
            sys.exit(clap_error(prog, f"unexpected argument '{a}' found", tip))
        if filename is None:
            filename = a
        else:
            sys.exit(clap_error(prog, f"unexpected argument '{a}' found"))
        i+=1
    return prog, sorted_flag, echo, debug, filename

def read_input(filename):
    if filename is not None:
        try:
            with open(filename, 'r', encoding='utf-8', errors='replace') as f:
                return f.read(), filename
        except FileNotFoundError:
            sys.stderr.write("\nthread 'main' (1) panicked at src/main.rs:44:47:\n")
            sys.stderr.write('Could not read file: Os { code: 2, kind: NotFound, message: "No such file or directory" }\n')
            sys.stderr.write("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
            sys.exit(101)
        except PermissionError:
            sys.stderr.write("\nthread 'main' (1) panicked at src/main.rs:44:47:\n")
            sys.stderr.write('Could not read file: Os { code: 13, kind: PermissionDenied, message: "Permission denied" }\n')
            sys.stderr.write("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
            sys.exit(101)
    else:
        # Read piped data if present; otherwise mimic the nonblocking stdin error.
        try:
            if sys.stdin.isatty():
                data = ''
            else:
                data = sys.stdin.read()
        except Exception:
            data = ''
        return data, 'stdin'

def no_tty_error():
    # The original reports slightly different OS errors depending on whether it
    # has data/file input.  This message is the common captured case for TUI init.
    sys.stderr.write('Error: Os { code: 6, kind: Uncategorized, message: "No such device or address" }\n')
    return 1

def main(argv):
    parsed = parse_args(argv)
    if parsed is None:
        return 0
    prog, sorted_flag, echo, debug, filename = parsed
    data, title = read_input(filename)
    if echo:
        # Printed before alternate screen; on a pty newlines become CRLF by the terminal.
        sys.stdout.write(data)
        if not data.endswith('\n'):
            sys.stdout.write('\n')
        sys.stdout.write('\n')
        sys.stdout.flush()
    if not sys.stdin.isatty():
        if filename is None and not data:
            sys.stderr.write('Error: Os { code: 11, kind: WouldBlock, message: "Resource temporarily unavailable" }\n')
            return 1
        return no_tty_error()
    model = Model(data, sorted_flag)
    app = App(model, title, debug)
    try:
        app.run()
    except KeyboardInterrupt:
        pass
    except OSError as e:
        return no_tty_error()
    return 0

if __name__ == '__main__':
    sys.exit(main(sys.argv))
